<section class="container section"><div class="section-header"><h1>Browse Recipes</h1><form method="get"><label>Sort<select name="sort" onchange="this.form.submit()"><option value="latest" <?= $sort === 'latest' ? 'selected' : '' ?>>Latest</option><option value="rating" <?= $sort === 'rating' ? 'selected' : '' ?>>Top rated</option><option value="title" <?= $sort === 'title' ? 'selected' : '' ?>>Title</option></select></label></form></div><?php if ($recipes): ?><div class="recipe-grid"><?php foreach ($recipes as $recipe): ?><?php include TEMPLATES_PATH . '/partials/recipe-card.php'; ?><?php endforeach; ?></div><?php else: ?><p>No recipes found yet.</p><?php endif; ?></section>
